package dev.ankigate;
public final class UpdatePolicyChecks {
 static {if(UpdatePolicy.newer(7,7)||UpdatePolicy.newer(6,7)||!UpdatePolicy.newer(8,7))throw new AssertionError("same/older manifest must be no-op");}
 static void rejects(Runnable r){try{r.run();throw new AssertionError("accepted invalid update");}catch(IllegalArgumentException expected){}}
 public static void main(String[] args){String hash="a".repeat(64);UpdatePolicy.https("https://pop.382910.xyz/update.json");rejects(()->UpdatePolicy.https("http://example.com/a"));rejects(()->UpdatePolicy.https("https://user@example.com/a"));rejects(()->UpdatePolicy.https("file:///a"));UpdatePolicy.metadata(8,100,hash);rejects(()->UpdatePolicy.metadata(8,UpdatePolicy.MAX_SIZE+1,hash));rejects(()->UpdatePolicy.metadata(8,100,"bad"));UpdatePolicy.downloaded(100,100,hash,hash.toUpperCase());rejects(()->UpdatePolicy.downloaded(99,100,hash,hash));rejects(()->UpdatePolicy.downloaded(100,100,"b".repeat(64),hash));UpdatePolicy.archive("dev.ankigate",8,8,7,true);rejects(()->UpdatePolicy.archive("other",8,8,7,true));rejects(()->UpdatePolicy.archive("dev.ankigate",7,8,6,true));rejects(()->UpdatePolicy.archive("dev.ankigate",7,7,7,true));rejects(()->UpdatePolicy.archive("dev.ankigate",8,8,7,false));for(int t:new int[]{1,3,4})for(int e=1;e<=4;e++)if(QualifiedPolicy.accepts(t,e)!=(e>=t))throw new AssertionError("threshold boundary");if(QualifiedPolicy.accepts(1,5)||QualifiedPolicy.accepts(1,0))throw new AssertionError("invalid ease");System.out.println("HTTPS, metadata bounds, size/hash, package/version/signature and threshold boundaries passed");}
}
